__NUXT_JSONP__("/jp/freetrial/thanks", {data:[{details:{slug:"jp",pageTitle:"無料体験レッスンをご予約いただきありがとうございます！ | Mentor Language Institute",pageDescription:"お問合せを受け付けました。2-3日以内にご連絡させて頂きます。",title:"無料体験レッスンをご予約いただきありがとうございます！",subtitle:["お問合せを受け付けました。\u003Cbr \u002F\u003E2-3日以内にご連絡させて頂きます。","お急ぎの際はお電話でも質問を受け付けております。 \u003Cbr \u002F\u003E お気軽にどうぞ！","Mentor Language Institute \u003Cbr \u002F\u003Eスタッフ一同","【ウェストウッドキャンパス】 \u003Cbr \u002F\u003E10880 Wilshire Blvd., Suite 122, Los Angeles CA 90024\u003Cbr \u002F\u003E電話：＋1（310）887-0777","【ハリウッドキャンパス】 \u003Cbr \u002F\u003E7080 Hollywood Blvd., Suite 314, Los Angeles CA 90028 \u003Cbr \u002F\u003E電話：＋1（323）870-7102","【日本事務局】 \u003Cbr \u002F\u003E東京都新宿区西新宿2-6- 1 新宿住友ビル43階 \u003Cbr \u002F\u003E（スクールアライアンス内） \u003Cbr \u002F\u003E電話：03-6692-6731"],dir:"\u002Ffreetrial-thanks",path:"\u002Ffreetrial-thanks\u002Fjp",extension:".json",createdAt:"2026-10-22T16:31:29.367Z",updatedAt:"2025-05-26T12:06:27.761Z"}}],fetch:{},mutations:void 0});